-- Migration-of-record (data only). Applied out-of-band, branch-first, per
-- .claude rules — do NOT run `prisma migrate deploy` against prod.
--
-- Fee cascade: editing an auto-generated grade fee used to send no gradeId,
-- so updateFeeStructure set FeeStructure.gradeId to NULL (the sync engine
-- still matched it via sourceSignals.gradeId, but the grade column went
-- blank). Restore the grade from sourceSignals where that grade still exists.
-- Idempotent.

UPDATE "FeeStructure" fs
SET "gradeId" = fs."sourceSignals"->>'gradeId'
WHERE fs."isAutoGenerated" = true
  AND fs."gradeId" IS NULL
  AND fs."sourceSignals"->>'gradeId' IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM "academic_grades" g
    WHERE g."id" = fs."sourceSignals"->>'gradeId'
      AND g."schoolId" = fs."schoolId"
  );
